algorithms.pseudocode:
function RADICAL(n):
    if n <= 1: return max(n, 0)
    rad = 1
    d = 2
    while d*d <= n:
        if n mod d == 0:
            rad *= d
            while n mod d == 0: n /= d
        d += 1
    if n > 1: rad *= n
    return rad

Time: O(sqrt(n)), Space: O(log n)

function CHECK_OBSTRUCTION(m, x, y, z):
    for a in 1..m-1 with gcd(a,m) = 1:
        for b in 1..m-1 with gcd(b,m) = 1:
            target = (a^x + b^y) mod m
            for c in 1..m-1 with gcd(c,m) = 1:
                if c^z mod m == target:
                    return False
    return True

Time: O(m^3) per modulus
